CREATE FUNCTION public.save_sports_profile(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; PERFORM 1 FROM public.profiles WHERE id=uid FOR UPDATE; UPDATE public.profiles SET nome=payload->>'nome',atuacao=payload->>'atuacao',cidade=payload->>'cidade',modalidades=ARRAY(SELECT jsonb_array_elements_text(payload->'modalidades')),bio=payload->>'bio',avatar_path=payload->>'avatar_path' WHERE id=uid; DELETE FROM public.podios WHERE user_id=uid; INSERT INTO public.podios(user_id,titulo,posicao,ano) SELECT uid,x->>'titulo',(x->>'posicao')::integer,(x->>'ano')::integer FROM jsonb_array_elements(payload->'podios') x; DELETE FROM public.marcas WHERE user_id=uid; INSERT INTO public.marcas(user_id,prova,valor) SELECT uid,x->>'prova',x->>'valor' FROM jsonb_array_elements(payload->'marcas') x; END; $$;
REVOKE ALL ON FUNCTION public.save_sports_profile(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_sports_profile(jsonb) TO authenticated;